    'table-formatting-free' => 'लेआउट या रिक्ति बदल सकती है',
    'table-formatting-paid' => 'अधिकांश फ़ॉर्मेटिंग को सटीक रखता है',
    'table-ocr' => 'ओसीआर गुणवत्ता',
    'table-ocr-free' => 'मूल पाठ पहचान गुणवत्ता',
    'table-ocr-paid' => 'बेहतर परिणामों के साथ उन्नत ओसीआर',
    'when-to-choose-heading' => 'कब कौन सा विकल्प चुनें?',
    'when-to-choose-para' => 'जब आप छोटी फ़ाइलों पर काम करते हैं या त्वरित और सरल रूपांतरण की आवश्यकता होती है, तो एक निःशुल्क पीडीएफ से वर्ड कनवर्टर चुनें। सशुल्क टूल तब सबसे अच्छा काम करते हैं जब आप कई फ़ाइलों को संभालते हैं, उच्च सटीकता की आवश्यकता होती है, और अक्सर ओसीआर का उपयोग करते हैं। जब गुणवत्ता सबसे अधिक मायने रखती है तो सशुल्क विकल्पों के साथ रहने से समय की बचत हो सकती है।',
    'common-issues-heading' => 'सामान्य मुद्दे और उन्हें कैसे ठीक करें',
    'common-issues-intro' => 'ऑनलाइन टूल का उपयोग करते समय आपको रूपांतरण समस्याओं का सामना करना पड़ सकता है। यहां कुछ सामान्य समस्याएं और उन्हें ठीक करने के तरीके बताए गए हैं।',
    'issue1-heading' => '1. फ़ॉर्मेटिंग ब्रेक',
    'issue1-para1' => 'जब आप पीडीएफ को वर्ड में कनवर्ट करते हैं, तो फ़ॉर्मेटिंग कभी-कभी टूट सकती है। इससे पैराग्राफ या शीर्षक अलग दिखते हैं। एक विश्वसनीय कनवर्टर का उपयोग करने से मूल लेआउट को बनाए रखने में मदद मिल सकती है। Word में शैलियों को मैन्युअल रूप से समायोजित करने से छोटी संरेखण समस्याएं भी जल्दी ठीक हो जाती हैं। दस्तावेज़ को अंतिम रूप देने से पहले पेज ब्रेक की जाँच करना यह सुनिश्चित करता है कि सब कुछ व्यवस्थित रहे।',
    'issue1-para2' => 'एक समय में छोटे अनुभागों को परिवर्तित करने से अक्सर स्वरूपण त्रुटियाँ कम हो जाती हैं।',
    'issue2-heading' => '2. छवियाँ स्थानांतरण',
    'issue2-para1' => 'जब आप पीडीएफ को वर्ड में कनवर्ट करते हैं तो छवियां बदल सकती हैं या हिल सकती हैं, खासकर जटिल लेआउट में। डिज़ाइन को सुरक्षित रखने वाले टूल का उपयोग करने से छवियों को यथास्थान बनाए रखने में मदद मिलती है। रूपांतरण के बाद वर्ड में छवि स्थिति को समायोजित करने से उचित संरेखण बहाल हो जाता है। अंतिम दस्तावेज़ को वर्ड टेम्पलेट के रूप में सहेजने से भविष्य में होने वाले बदलावों को रोका जा सकता है।',
    'issue2-para2' => 'दृश्य सटीकता बनाए रखने के लिए हमेशा छवियों के साथ तालिकाओं और चार्टों को सत्यापित करें।',
    'issue3-heading' => '3. स्कैन की गई पीडीएफ़ में टेक्स्ट डिटेक्शन त्रुटियाँ',
    'issue3-para1' => 'स्कैन की गई पीडीएफ़ रूपांतरण के दौरान पाठ पहचान त्रुटियों का कारण बन सकती है। कनवर्टर में OCR को सक्षम करने से अक्षरों और संख्याओं की पहचान में सुधार होता है। परिवर्तित वर्ड फ़ाइल की समीक्षा करना और गलतियों को सुधारना सटीकता सुनिश्चित करता है। उच्च-गुणवत्ता वाले स्कैन बेहतर परिणाम देते हैं और मैन्युअल संपादन को कम करते हैं।',
    'issue3-para2' => 'OCR का बार-बार उपयोग करने से पेचीदा दस्तावेज़ों में पहचान में भी सुधार हो सकता है।',
    'conclusion-heading' => 'निष्कर्ष: 2026 में पीडीएफ़ संपादित करने का एक आसान तरीका',
    'conclusion-para1' => 'पीडीएफ फाइलें अक्सर संपादन को प्रतिबंधित करती हैं, इसलिए उपयोगकर्ताओं को पीडीएफ को वर्ड में कुशलतापूर्वक परिवर्तित करने के लिए टूल की आवश्यकता होती है। आधुनिक कन्वर्टर्स अब टेक्स्ट को संपादन योग्य बनाते हुए लेआउट, टेबल और छवियों को बनाए रखते हैं।',
    'conclusion-para2' => 'ओसीआर समर्थन स्कैन किए गए दस्तावेज़ों में मदद करता है, जिससे सटीक पाठ पहचान सुनिश्चित होती है। मुफ़्त टूल छोटी फ़ाइलों और त्वरित रूपांतरणों के लिए अच्छा काम करते हैं, जबकि भुगतान किए गए विकल्प बड़े दस्तावेज़ों को उच्च गति और बेहतर फ़ॉर्मेटिंग के साथ संभालते हैं।',
    'faqs-heading' => 'पूछे जाने वाले प्रश्न',
    'faq1-question' => '2026 में सबसे अच्छा पीडीएफ टू वर्ड कनवर्टर कौन सा है?',
    'faq1-answer' => 'किसी एक नाम का उल्लेख करना कठिन है, क्योंकि पीडीएफ से वर्ड रूपांतरण के कई विश्वसनीय उपकरण मौजूद हैं। हालाँकि, Adobe Acrobat Online उच्च सटीकता प्रदान करता है और फ़ॉर्मेटिंग को अच्छी तरह से संरक्षित करता है। Smallpdf और PDFelement भी विभिन्न आवश्यकताओं के लिए विश्वसनीय विकल्प हैं।',
    'faq2-question' => 'क्या फ़ॉर्मेटिंग खोए बिना पीडीएफ को वर्ड में बदलने के लिए कोई मुफ़्त टूल है?',
    'faq2-answer' => 'Google Docs और Smallpdf अच्छे फ़ॉर्मेटिंग प्रतिधारण के साथ मुफ़्त रूपांतरण प्रदान करते हैं। Word में अभी भी कुछ छोटे समायोजन की आवश्यकता हो सकती है।',
    'faq3-question' => 'क्या मैं स्कैन की गई पीडीएफ़ परिवर्तित कर सकता हूँ?',
    'faq3-answer' => 'हाँ, OCR समर्थन वाले कन्वर्टर, जैसे PDFelement, स्कैन किए गए PDF में टेक्स्ट को पहचान सकते हैं। सटीकता स्कैन की गुणवत्ता और स्पष्टता पर निर्भर करती है।',
    'faq4-question' => 'पीडीएफ़ परिवर्तित करने के बाद फ़ॉर्मेटिंग क्यों टूट जाती है?',
    'faq4-answer' => 'फ़ॉर्मेटिंग ब्रेक तब होते हैं जब लेआउट, टेबल या फ़ॉन्ट पूरी तरह से स्थानांतरित नहीं होते हैं। एक विश्वसनीय कनवर्टर का उपयोग आमतौर पर इन समस्याओं को कम करता है।',
    'faq5-question' => 'मुफ़्त पीडीएफ कन्वर्टर्स के पास कौन सी फ़ाइल आकार सीमाएँ हैं?',
    'faq5-answer' => 'मुफ़्त कन्वर्टर अक्सर दैनिक उपयोग या फ़ाइल आकार को प्रतिबंधित करते हैं। बड़े PDF को कुशलतापूर्वक संसाधित करने के लिए सशुल्क टूल की आवश्यकता हो सकती है।',
    'intro-parag' => 'अधिकतम दक्षता के साथ पीडीएफ को वर्ड में कैसे परिवर्तित करें, इस पर एक विस्तृत मार्गदर्शिका निम्नलिखित है। हम कुछ <a href="__LINK__">विश्वसनीय मुफ्त पीडीएफ से वर्ड कन्वर्टर्स</a> पर भी चर्चा करेंगे।',
    'issue2-parag' => 'जब आप पीडीएफ को वर्ड में कनवर्ट करते हैं तो छवियां बदल सकती हैं या हिल सकती हैं, खासकर जटिल लेआउट में। डिज़ाइन को सुरक्षित रखने वाले टूल का उपयोग करने से छवियों को यथास्थान बनाए रखने में मदद मिलती है। लेआउट बदलाव के लिए <a href="__LINK__">विशेषज्ञ युक्तियों</a> का पालन करने से रूपांतरण के बाद आपकी छवियों को यथास्थान बनाए रखने में मदद मिल सकती है।',
    'descriptions' => '2026 में फ़ॉर्मेटिंग खोए बिना पीडीएफ को वर्ड में कनवर्ट करें। सटीक, स्वच्छ रूपांतरण के लिए सर्वोत्तम टूल, चरण-दर-चरण तरीके और विशेषज्ञ युक्तियाँ जानें। अब जांचें!',
    'references-heading' => 'संदर्भ और उद्धरण',
    'ref1-title' => 'Adobe PDF से DOCX संदर्भ विशिष्टता',
    'ref1-text' => 'पीडीएफ से Office Open XML में टैग संरचना अनुवाद का विवरण देने वाला आधिकारिक इंजीनियरिंग दस्तावेज़।',
    'ref2-title' => 'Tesseract OCR ओपन सोर्स इंजन',
    'ref2-text' => 'दस्तावेज़ लेआउट में ऑप्टिकल कैरेक्टर पहचान के लिए तकनीकी विनिर्देश और दिशानिर्देश।',
    'ref3-title' => 'W3C संरचनात्मक अभिगम्यता दिशानिर्देश',
    'ref3-text' => 'दस्तावेज़ रूपांतरण के दौरान संरचित टैगिंग और सिमेंटिक संरक्षण के लिए मानक।',
];
